/**
 * Alert FSM - Finite State Machine for Alert visibility/dismissal
 *
 * This FSM models the visibility lifecycle of an Alert component,
 * respecting the existing show, dismissible, and onClose semantics.
 *
 * States:
 * - visible: Alert is rendered and visible to the user
 * - dismissing: Alert is playing the fade-out exit animation
 * - hidden: Alert is not rendered (returns null)
 *
 * Events:
 * - SHOW: External request to show (show prop becomes true)
 * - HIDE: External request to hide (show prop becomes false)
 * - DISMISS_CLICK: Close button clicked
 * - DISMISS_ESCAPE: Escape key pressed when dismissible
 * - AUTO_DISMISS_TIMEOUT: Auto-dismiss timer expired
 * - ANIMATION_END: Dismiss animation completed
 */

/**
 * Visibility states for the Alert FSM
 */
export type AlertVisibilityState = 'visible' | 'dismissing' | 'hidden';

/**
 * The Alert FSM state object
 */
export interface AlertFSMState {
  readonly visibility: AlertVisibilityState;
}

/**
 * Events that trigger state transitions in the Alert FSM
 */
export type AlertFSMEvent =
  | { readonly type: 'SHOW' }
  | { readonly type: 'HIDE' }
  | { readonly type: 'DISMISS_CLICK' }
  | { readonly type: 'DISMISS_ESCAPE' }
  | { readonly type: 'AUTO_DISMISS_TIMEOUT' }
  | { readonly type: 'ANIMATION_END' };

/**
 * Creates the initial FSM state based on the show prop
 *
 * @param show - Whether the alert should initially be visible
 * @returns The initial FSM state
 */
export function createInitialAlertFSMState(show: boolean): AlertFSMState {
  return {
    visibility: show ? 'visible' : 'hidden',
  };
}

/**
 * Pure reducer function for the Alert FSM
 *
 * Transitions:
 * - From "visible":
 *   - HIDE → "hidden" (immediate, external control)
 *   - DISMISS_CLICK → "dismissing"
 *   - DISMISS_ESCAPE → "dismissing"
 *   - AUTO_DISMISS_TIMEOUT → "dismissing"
 *   - SHOW → stays "visible" (idempotent)
 *   - ANIMATION_END → stays "visible" (no-op)
 *
 * - From "dismissing":
 *   - ANIMATION_END → "hidden"
 *   - SHOW → "visible" (cancel animation, re-show)
 *   - HIDE → "hidden" (force hide)
 *   - DISMISS_* / AUTO_DISMISS_TIMEOUT → stays "dismissing"
 *
 * - From "hidden":
 *   - SHOW → "visible"
 *   - HIDE → stays "hidden" (idempotent)
 *   - DISMISS_* / AUTO_DISMISS_TIMEOUT → stays "hidden" (no-op)
 *   - ANIMATION_END → stays "hidden" (no-op)
 *
 * @param state - Current FSM state
 * @param event - Event triggering the transition
 * @returns New FSM state
 */
export function alertFSMReducer(state: AlertFSMState, event: AlertFSMEvent): AlertFSMState {
  switch (state.visibility) {
    case 'visible':
      switch (event.type) {
        case 'HIDE':
          return { visibility: 'hidden' };
        case 'DISMISS_CLICK':
        case 'DISMISS_ESCAPE':
        case 'AUTO_DISMISS_TIMEOUT':
          return { visibility: 'dismissing' };
        case 'SHOW':
        case 'ANIMATION_END':
          return state;
        default:
          return state;
      }

    case 'dismissing':
      switch (event.type) {
        case 'ANIMATION_END':
          return { visibility: 'hidden' };
        case 'SHOW':
          return { visibility: 'visible' };
        case 'HIDE':
          return { visibility: 'hidden' };
        case 'DISMISS_CLICK':
        case 'DISMISS_ESCAPE':
        case 'AUTO_DISMISS_TIMEOUT':
          return state;
        default:
          return state;
      }

    case 'hidden':
      switch (event.type) {
        case 'SHOW':
          return { visibility: 'visible' };
        case 'HIDE':
        case 'DISMISS_CLICK':
        case 'DISMISS_ESCAPE':
        case 'AUTO_DISMISS_TIMEOUT':
        case 'ANIMATION_END':
          return state;
        default:
          return state;
      }

    default:
      return state;
  }
}

import React, {
  cloneElement,
  forwardRef,
  isValidElement,
  memo,
  useCallback,
  useEffect,
  useMemo,
  useReducer,
  useRef,
} from 'react';

import { useReducedMotion } from '../../hooks/useReducedMotion/useReducedMotion';
import { cn } from '../../utils';
import { isEscapeKey } from '../../utils/keyboard';
import { isSafeHref } from '../../utils/validation';

import { alertFSMReducer, createInitialAlertFSMState } from './Alert.fsm';

import type { AlertHeadingProps, AlertLinkProps, AlertProps } from './Alert.types';

/**
 * Alert Link - styled link for use within alerts
 * SECURITY: Validates href, prevents XSS, adds external link protection
 *
 * @example
 * ```tsx
 * <Alert variant="info">
 *   Check out the <Alert.Link href="/docs">documentation</Alert.Link>.
 * </Alert>
 *
 * // External link with target="_blank" automatically gets rel="noopener noreferrer"
 * <Alert variant="warning">
 *   <Alert.Link href="https://example.com" target="_blank">
 *     External site
 *   </Alert.Link>
 * </Alert>
 * ```
 */
const AlertLink = React.memo(
  forwardRef<HTMLAnchorElement, AlertLinkProps>(function AlertLink(
    {
      children,
      href = '#',
      onClick,
      className = '',
      target,
      rel,
      'data-testid': dataTestId,
      'data-test': dataTest,
      title,
    },
    ref
  ) {
    // Validate href against XSS patterns
    const safeHref = isSafeHref(href, { undefinedBehavior: 'unsafe' }) ? href : '#';

    // External link protection: target="_blank" requires rel="noopener noreferrer"
    // This prevents the opened page from accessing window.opener — merge with user-provided rel
    const isExternal = target === '_blank';
    const safeRel = isExternal
      ? [...new Set([...(rel ? rel.split(/\s+/) : []), 'noopener', 'noreferrer'])].join(' ')
      : rel;

    const computedClassName = cn('alert-link', className);

    return (
      <a
        ref={ref}
        href={safeHref}
        className={computedClassName}
        onClick={onClick}
        target={target}
        rel={safeRel}
        data-testid={dataTestId}
        data-test={dataTest}
        title={title}
      >
        {children}
      </a>
    );
  })
);

AlertLink.displayName = 'Alert.Link';

/**
 * Alert Heading - styled heading for use within alerts
 *
 * @example
 * ```tsx
 * <Alert variant="success">
 *   <Alert.Heading>Well done!</Alert.Heading>
 *   <p>You successfully completed the task.</p>
 * </Alert>
 * ```
 */
const AlertHeading = React.memo(
  forwardRef<HTMLHeadingElement, AlertHeadingProps>(function AlertHeading(
    { children, as: Component = 'h4', className = '' },
    ref
  ) {
    const classes = cn('alert-heading', className);

    return (
      <Component ref={ref} className={classes}>
        {children}
      </Component>
    );
  })
);

AlertHeading.displayName = 'Alert.Heading';

/**
 * Alert Component
 *
 * A Bootstrap 5 alert component for displaying important messages to users.
 * Supports multiple variants, dismissible functionality, and accessibility features.
 *
 * SECURITY FEATURES:
 * - Prop whitelisting for Alert and Alert.Link
 * - href validation to prevent XSS attacks
 * - External link protection (rel="noopener noreferrer" for target="_blank")
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - Proper ARIA roles (alert vs status) based on severity
 * - aria-live announcements with aria-atomic for complete announcements
 * - Keyboard support (Escape to dismiss)
 * - Decorative icons hidden with aria-hidden
 *
 * PERFORMANCE FEATURES:
 * - Memoized class name construction
 * - Memoized subcomponents (AlertLink, AlertHeading)
 *
 * @see https://getbootstrap.com/docs/5.3/components/alerts/
 *
 * @example
 * ```tsx
 * // Basic alert
 * <Alert variant="info">This is an informational message.</Alert>
 *
 * // Alert with title
 * <Alert variant="success">
 *   <Alert.Heading>Success!</Alert.Heading>
 *   <p>Your changes have been saved successfully.</p>
 * </Alert>
 *
 * // Dismissible alert with Escape key support
 * const [show, setShow] = useState(true);
 * {show && (
 *   <Alert variant="warning" dismissible onClose={() => setShow(false)}>
 *     This alert can be dismissed.
 *   </Alert>
 * )}
 *
 * // Alert with secure external link
 * <Alert variant="danger">
 *   An error occurred. <Alert.Link href="https://example.com" target="_blank">Get help</Alert.Link>.
 * </Alert>
 *
 * // Alert with validated href (XSS prevention)
 * <Alert variant="info">
 *   Visit our <Alert.Link href="/docs">documentation</Alert.Link>.
 * </Alert>
 * ```
 */
const AlertBase = memo(
  forwardRef<HTMLDivElement, AlertProps>(
    (
      {
        children,
        variant = 'primary',
        title,
        dismissible = false,
        onClose,
        icon,
        show = true,
        className = '',
        style,
        id,
        as: Component = 'div',
        'aria-atomic': ariaAtomic = true,
        'data-testid': dataTestId,
        'data-test': dataTest,
        iconLabel,
        autoDismiss,
        transition = true,
      },
      ref
    ) => {
      // Initialize FSM state from show prop
      const [fsmState, dispatch] = useReducer(alertFSMReducer, show, createInitialAlertFSMState);

      const alertRef = useRef<HTMLDivElement | null>(null);
      const prefersReducedMotion = useReducedMotion();
      const shouldAnimate = transition && !prefersReducedMotion;

      // Synchronize external show prop with FSM
      useEffect(() => {
        dispatch({ type: show ? 'SHOW' : 'HIDE' });
      }, [show]);

      // Determine ARIA role based on variant
      // danger/warning are assertive (role="alert"), others are polite (role="status")
      const role = variant === 'danger' || variant === 'warning' ? 'alert' : 'status';

      // Handle close button click - dispatch FSM event and call onClose
      const handleClose = useCallback(() => {
        dispatch({ type: 'DISMISS_CLICK' });
        if (!shouldAnimate) {
          dispatch({ type: 'ANIMATION_END' });
        }
        onClose?.('click');
      }, [onClose, shouldAnimate]);

      // Handle Escape key to dismiss - dispatch FSM event and call onClose
      const handleKeyDown = useCallback(
        (event: KeyboardEvent) => {
          if (
            dismissible &&
            onClose &&
            isEscapeKey(event) &&
            alertRef.current?.contains(document.activeElement)
          ) {
            dispatch({ type: 'DISMISS_ESCAPE' });
            if (!shouldAnimate) {
              dispatch({ type: 'ANIMATION_END' });
            }
            onClose('escape');
          }
        },
        [dismissible, onClose, shouldAnimate]
      );

      useEffect(() => {
        if (dismissible && onClose) {
          document.addEventListener('keydown', handleKeyDown);
          return () => {
            document.removeEventListener('keydown', handleKeyDown);
          };
        }
        return undefined;
      }, [dismissible, onClose, handleKeyDown]);

      // Auto-dismiss timer
      useEffect(() => {
        if (!autoDismiss || autoDismiss <= 0 || fsmState.visibility !== 'visible') {
          return undefined;
        }

        const timerId = setTimeout(() => {
          dispatch({ type: 'AUTO_DISMISS_TIMEOUT' });
          if (!shouldAnimate) {
            dispatch({ type: 'ANIMATION_END' });
          }
          onClose?.('timeout');
        }, autoDismiss);

        return () => {
          clearTimeout(timerId);
        };
      }, [autoDismiss, fsmState.visibility, onClose, shouldAnimate]);

      // Handle dismiss animation end via CSS transitionend
      useEffect(() => {
        if (fsmState.visibility !== 'dismissing' || !shouldAnimate) {
          return undefined;
        }

        const element = alertRef.current;
        if (!element) {
          dispatch({ type: 'ANIMATION_END' });
          return undefined;
        }

        const handleTransitionEnd = (event: TransitionEvent): void => {
          // Only react to opacity transitions on this element
          if (event.target === element && event.propertyName === 'opacity') {
            dispatch({ type: 'ANIMATION_END' });
          }
        };

        element.addEventListener('transitionend', handleTransitionEnd);

        // Safety timeout in case transitionend doesn't fire (e.g., display: none)
        const safetyTimer = setTimeout(() => {
          dispatch({ type: 'ANIMATION_END' });
        }, 300);

        return () => {
          element.removeEventListener('transitionend', handleTransitionEnd);
          clearTimeout(safetyTimer);
        };
      }, [fsmState.visibility, shouldAnimate]);

      // Memoize Bootstrap class names construction (must be before visibility check for hook ordering)
      const bootstrapClasses = useMemo(
        () =>
          cn(
            'alert', // Base Bootstrap alert class
            `alert-${variant}`, // Variant: alert-primary, alert-success, etc.
            dismissible && 'alert-dismissible', // Dismissible styling
            'fade', // Always include fade for transition support
            fsmState.visibility === 'visible' && 'show', // Show class for visible state
            className // Allow additional custom classes
          ),
        [variant, dismissible, className, fsmState.visibility]
      );

      const iconClasses = 'd-inline-flex align-items-center flex-shrink-0 me-2';

      const renderedIcon = useMemo(() => {
        if (!icon) {
          return null;
        }

        if (
          isValidElement<{
            className?: string;
            'aria-label'?: string;
            'aria-hidden'?: boolean;
            role?: string;
            children?: React.ReactNode;
          }>(icon)
        ) {
          const iconElement = icon;
          const existingClassName = iconElement.props.className;
          const existingAriaLabel = iconElement.props['aria-label'];
          const existingAriaHidden = iconElement.props['aria-hidden'];
          const ariaLabel = iconLabel ?? existingAriaLabel;
          const ariaHidden = iconLabel ? undefined : (existingAriaHidden ?? true);

          return cloneElement(iconElement, {
            className: cn(iconClasses, existingClassName),
            'aria-label': ariaLabel,
            'aria-hidden': ariaHidden,
            role: ariaLabel ? 'img' : iconElement.props.role,
          });
        }

        return (
          <span className={iconClasses} aria-hidden="true">
            {icon}
          </span>
        );
      }, [icon, iconLabel]);

      // Don't render if FSM state is hidden
      if (fsmState.visibility === 'hidden') {
        return null;
      }

      // Merge forwarded ref with internal alertRef
      const mergeRefs = (node: HTMLDivElement | null): void => {
        alertRef.current = node;
        if (typeof ref === 'function') {
          ref(node);
        } else if (ref) {
          (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }
      };

      return (
        <Component
          ref={mergeRefs}
          className={bootstrapClasses}
          role={role}
          style={style}
          id={id}
          aria-live={variant === 'danger' || variant === 'warning' ? 'assertive' : 'polite'}
          aria-atomic={ariaAtomic}
          data-testid={dataTestId}
          data-test={dataTest}
          data-visual-state={fsmState.visibility}
        >
          {/* Optional icon */}
          {renderedIcon}

          {/* Optional title using Alert.Heading */}
          {title && <AlertHeading>{title}</AlertHeading>}

          {/* Alert content */}
          {children}

          {/* Dismiss button */}
          {dismissible && onClose && (
            <button type="button" className="btn-close" aria-label="Close" onClick={handleClose} />
          )}
        </Component>
      );
    }
  )
);

AlertBase.displayName = 'Alert';

// Create compound component
type AlertComponent = typeof AlertBase & {
  Link: typeof AlertLink;
  Heading: typeof AlertHeading;
};

export const Alert = AlertBase as AlertComponent;
Alert.Link = AlertLink;
Alert.Heading = AlertHeading;

import type { SafeHTMLAttributes, SemanticColorVariant } from '../../types';
import type { ReactNode } from 'react';

/**
 * Alert component variants
 * Maps to Bootstrap 5 alert contextual classes
 *
 * @see https://getbootstrap.com/docs/5.3/components/alerts/
 * @see SemanticColorVariant
 */
export type AlertVariant = SemanticColorVariant;

/**
 * Reason for alert dismissal
 * - 'click': User clicked the close button
 * - 'escape': User pressed the Escape key
 * - 'timeout': Auto-dismiss timer expired
 */
export type AlertDismissReason = 'click' | 'escape' | 'timeout';

/**
 * Whitelisted HTML attributes for safe prop spreading in Alert component
 * SECURITY: Restricts arbitrary props to prevent injection attacks
 * @see SafeHTMLAttributes
 */
export type SafeAlertHTMLAttributes = SafeHTMLAttributes<HTMLDivElement>;

/**
 * Whitelisted HTML attributes for safe prop spreading in AlertLink component
 * SECURITY: Only allows safe anchor attributes, prevents href injection
 * @see SafeHTMLAttributes
 */
export type SafeAlertLinkHTMLAttributes = SafeHTMLAttributes<HTMLAnchorElement>;

/**
 * Alert component props
 *
 * @example
 * ```tsx
 * // Basic alert
 * <Alert variant="info">This is an informational message.</Alert>
 *
 * // Alert with title
 * <Alert variant="success" title="Success!">
 *   Your changes have been saved.
 * </Alert>
 *
 * // Dismissible alert
 * <Alert variant="warning" dismissible onClose={() => setShow(false)}>
 *   This alert can be dismissed.
 * </Alert>
 *
 * // Alert with custom icon
 * <Alert variant="danger" icon={<CustomIcon />}>
 *   Something went wrong.
 * </Alert>
 * ```
 */
export interface AlertProps extends SafeAlertHTMLAttributes {
  /**
   * Alert content
   */
  children: ReactNode;

  /**
   * Alert color variant
   * @default 'primary'
   */
  variant?: AlertVariant;

  /**
   * Optional alert title (rendered as heading)
   */
  title?: string;

  /**
   * Whether the alert can be dismissed
   * @default false
   */
  dismissible?: boolean;

  /**
   * Callback when the alert is closed
   * Required when dismissible is true
   *
   * @param reason - Why the alert was dismissed:
   *   - `'click'`: close button clicked
   *   - `'escape'`: Escape key pressed
   *   - `'timeout'`: auto-dismiss timer expired
   */
  onClose?: (reason?: AlertDismissReason) => void;

  /**
   * Custom icon to display
   * If not provided, no icon is shown (Bootstrap default)
   */
  icon?: ReactNode;

  /**
   * Optional accessible label for the icon
   * When provided, the icon is treated as semantic (role="img"); otherwise it is decorative
   */
  iconLabel?: string;

  /**
   * Whether to show the alert
   * Useful for controlled visibility
   * @default true
   */
  show?: boolean;

  /**
   * Element to render as
   * @default 'div'
   */
  as?: 'div' | 'section';

  /**
   * Auto-dismiss the alert after the specified duration (in milliseconds)
   * Set to 0 or omit to disable auto-dismiss.
   * Requires onClose to be provided.
   */
  autoDismiss?: number;

  /**
   * Whether to animate the dismiss transition (fade-out)
   * Uses Bootstrap's `fade`/`show` CSS classes.
   * Respects the user's `prefers-reduced-motion` setting.
   * @default true
   */
  transition?: boolean;

  /**
   * Aria-atomic attribute for complete announcements
   * @default true for alerts with aria-live
   */
  'aria-atomic'?: boolean;
}

/**
 * Alert.Link component props
 * SECURITY: Href is validated to prevent javascript: and data: attacks
 */
export interface AlertLinkProps extends SafeAlertLinkHTMLAttributes {
  /**
   * Link content
   */
  children: ReactNode;

  /**
   * Link URL (SECURITY: validated against XSS patterns)
   * Safe protocols: http, https, mailto, tel, /
   * Blocked: javascript:, data:, text/html
   */
  href: string;

  /**
   * Click handler
   */
  onClick?: (event: React.MouseEvent<HTMLAnchorElement>) => void;

  /**
   * Link target
   * External links should use '_blank' with rel="noopener noreferrer"
   * @default '_self'
   */
  target?: '_blank' | '_self' | '_parent' | '_top';

  /**
   * Relationship attribute for external links
   * Auto-added for target="_blank" to prevent window.opener attacks
   */
  rel?: string;
}

/**
 * Alert.Heading component props
 */
export interface AlertHeadingProps {
  /**
   * Heading content
   */
  children: ReactNode;

  /**
   * Heading level
   * @default 'h4'
   */
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';

  /**
   * Additional CSS class names
   */
  className?: string;
}

export { Alert } from './Alert';
export type { AlertFSMEvent, AlertFSMState, AlertVisibilityState } from './Alert.fsm';

// FSM utilities for advanced use cases
export { alertFSMReducer, createInitialAlertFSMState } from './Alert.fsm';
export type {
  AlertDismissReason,
  AlertHeadingProps,
  AlertLinkProps,
  AlertProps,
  AlertVariant,
} from './Alert.types';
